/** Responsive image sets generated by `npm run images` into /public/images. */
export interface ImageSet {
  base: string;
  widths: number[];
  fallback: string;
  width: number;
  height: number;
}

export const images = {
  heroWorkspace: {
    base: '/images/hero-workspace',
    widths: [640, 960, 1280, 1672],
    fallback: '/images/hero-workspace-1280.jpg',
    width: 1672,
    height: 941,
  },
  aboutOffice: {
    base: '/images/about-office',
    widths: [640, 960, 1254],
    fallback: '/images/about-office-960.jpg',
    width: 1254,
    height: 1254,
  },
  ...serviceSets(),
  ctaWaves: {
    base: '/images/cta-waves',
    widths: [840],
    fallback: '/images/cta-waves-840.jpg',
    width: 840,
    height: 420,
  },
} satisfies Record<string, ImageSet>;

/**
 * Stock photography (assets/stock → `npm run images`), 16:10 focal-point crops.
 * Unsplash licence; sources are listed in assets/stock/SOURCES.md.
 */
const photo = (name: string, widths: number[]): ImageSet => ({
  base: `/images/photo-${name}`,
  widths,
  fallback: `/images/photo-${name}-${widths[1]}.jpg`,
  width: widths[widths.length - 1],
  height: Math.round(widths[widths.length - 1] / 1.6),
});

export const photos = {
  serviceWeb: photo('service-web', [640, 960, 1280, 1600]),
  serviceApp: photo('service-app', [640, 960, 1280, 1600]),
  serviceAds: photo('service-ads', [640, 960, 1280, 1600]),
  serviceVideo: photo('service-video', [640, 960, 1280, 1600]),
  serviceBrand: photo('service-brand', [640, 960, 1280, 1600]),
  serviceSocial: photo('service-social', [640, 960, 1280, 1600]),
  articleWebsite: photo('article-website', [480, 800, 1200, 1600]),
  articleApp: photo('article-app', [480, 800, 1200, 1600]),
  articleAds: photo('article-ads', [480, 800, 1200, 1600]),
  articleVideo: photo('article-video', [480, 800, 1200, 1600]),
  articleBrand: photo('article-brand', [480, 800, 1200, 1600]),
  articleTrends: photo('article-trends', [480, 800, 1200, 1600]),
} satisfies Record<string, ImageSet>;

/** Rendered service artwork (assets/renders/services.html) — backup if a photo fails to load. */
function serviceSets() {
  const set = (id: string): ImageSet => ({
    base: `/images/service-${id}`,
    widths: [640, 960, 1280],
    fallback: `/images/service-${id}-960.jpg`,
    width: 1280,
    height: 800,
  });
  return {
    serviceWeb: set('web'),
    serviceApp: set('app'),
    serviceAds: set('ads'),
    serviceVideo: set('video'),
    serviceBrand: set('brand'),
    serviceSocial: set('social'),
  };
}
